import math
from pycompss.api.task import task
from pycompss.api.api import compss_wait_on

@task(returns=1)
def block_lu(A00):
    b = len(A00)
    for k in range(b):
        for i in range(k + 1, b):
            factor = A00[i][k] / A00[k][k]
            A00[i][k] = factor
            for j in range(k + 1, b):
                A00[i][j] -= factor * A00[k][j]
    return A00


@task(returns=1)
def solve_lower(L00, A01):
    b = len(L00)
    m = len(A01[0])
    for k in range(b):
        for i in range(k + 1, b):
            for j in range(m):
                A01[i][j] -= L00[i][k] * A01[k][j]
    return A01


@task(returns=1)
def solve_upper(U00, A10):
    b = len(U00)
    m = len(A10)
    for k in range(b):
        for i in range(m):
            A10[i][k] /= U00[k][k]
            for j in range(k + 1, b):
                A10[i][j] -= A10[i][k] * U00[k][j]
    return A10


@task(returns=1)
def update_block(L10, U01, A11):
    m = len(A11)
    n = len(A11[0])
    b = len(L10[0])
    for i in range(m):
        for j in range(n):
            for k in range(b):
                A11[i][j] -= L10[i][k] * U01[k][j]
    return A11


def main(A, N):
    B = max(1, math.ceil(N / 4))

    num_blocks = math.ceil(N / B)
    A_blocks = []
    for i in range(num_blocks):
        row_blocks = []
        for j in range(num_blocks):
            row_start = i * B
            row_end = min((i + 1) * B, N)
            col_start = j * B
            col_end = min((j + 1) * B, N)

            block = []
            for r in range(row_start, row_end):
                block.append(A[r][col_start:col_end])
            row_blocks.append(block)
        A_blocks.append(row_blocks)

    for k in range(num_blocks):
        A_blocks[k][k] = block_lu(A_blocks[k][k])

        for j in range(k + 1, num_blocks):
            A_blocks[k][j] = solve_lower(A_blocks[k][k], A_blocks[k][j])

        for i in range(k + 1, num_blocks):
            A_blocks[i][k] = solve_upper(A_blocks[k][k], A_blocks[i][k])

        for i in range(k + 1, num_blocks):
            for j in range(k + 1, num_blocks):
                A_blocks[i][j] = update_block(A_blocks[i][k], A_blocks[k][j], A_blocks[i][j])

    A_blocks = compss_wait_on(A_blocks)

    for i in range(num_blocks):
        for j in range(num_blocks):
            row_start = i * B
            row_end = min((i + 1) * B, N)
            col_start = j * B
            col_end = min((j + 1) * B, N)

            block = A_blocks[i][j]
            for r_idx, r in enumerate(range(row_start, row_end)):
                A[r][col_start:col_end] = block[r_idx]

    return A
